                if dimension == "鐘舵€? and not re.match(r"^(confirmed|inferred|unresolved)\b", summary):
                    errors.append(f"STRATEGY-{match.group(1)} 鐘舵€?must begin with confirmed, inferred, or unresolved")
            location = values.get("浠ｇ爜/鏂囨。瀹氫綅")
            if location and not re.search(r"[^锛?锛?\s]+:\d+", location):
                errors.append(f"STRATEGY-{match.group(1)} {dimension} location must contain path:line")
            explanation = values.get("璇︾粏瑙ｉ噴")
            if explanation and len(explanation) < 30:
                errors.append(f"STRATEGY-{match.group(1)} {dimension} 璇︾粏瑙ｉ噴 is too short")
    if "RAG" not in text or "浠ｇ爜澶嶇敤" not in text:
        errors.append("report must explicitly state RAG and code-reuse conclusions")
    return errors


